/// Every colour token by its tokens.json name, for code that looks tokens up by name (tests, the CSS bridge).
public enum QuireColorToken: String, CaseIterable, Sendable {
    case spine
    case paper
    case canvas
    case sheet
    case raised
    case slip
    case slipEdge
    case knob
    case originalPage
    case scrimSolid
    case ink
    case ink2
    case ink3
    case inkDisabled
    case onSlip
    case onSlip2
    case rule
    case ruleStrong
    case onSlipEdge
    case hover
    case pressed
    case fill
    case slipHover
    case slipPressed
    case scrim
    case accent
    case accentFill
    case accentFillHover
    case accentFillPressed
    case controlOnPressed
    case onAccent
    case accentWash
    case accentWashHover
    case accentWashPressed
    case focus
    case selWash
    case selRule
    case selWashIdle
    case selRuleIdle
    case star
    case success
    case warning
    case danger
    case info
    case successWash
    case warningWash
    case dangerWash
    case infoWash
    case findWash
    case findCurrent
    case dangerFill
    case dangerFillHover
    case dangerFillPressed
    case onDanger

    /// The dynamic colour, Graphite-aware where the token has a substitution.
    public var color: NSColor {
        switch self {
        case .spine: return .qSpine
        case .paper: return .qPaper
        case .canvas: return .qCanvas
        case .sheet: return .qSheet
        case .raised: return .qRaised
        case .slip: return .qSlip
        case .slipEdge: return .qSlipEdge
        case .knob: return .qKnob
        case .originalPage: return .qOriginalPage
        case .scrimSolid: return .qScrimSolid
        case .ink: return .qInk
        case .ink2: return .qInk2
        case .ink3: return .qInk3
        case .inkDisabled: return .qInkDisabled
        case .onSlip: return .qOnSlip
        case .onSlip2: return .qOnSlip2
        case .rule: return .qRule
        case .ruleStrong: return .qRuleStrong
        case .onSlipEdge: return .qOnSlipEdge
        case .hover: return .qHover
        case .pressed: return .qPressed
        case .fill: return .qFill
        case .slipHover: return .qSlipHover
        case .slipPressed: return .qSlipPressed
        case .scrim: return .qScrim
        case .accent: return .qAccent
        case .accentFill: return .qAccentFill
        case .accentFillHover: return .qAccentFillHover
        case .accentFillPressed: return .qAccentFillPressed
        case .controlOnPressed: return .qControlOnPressed
        case .onAccent: return .qOnAccent
        case .accentWash: return .qAccentWash
        case .accentWashHover: return .qAccentWashHover
        case .accentWashPressed: return .qAccentWashPressed
        case .focus: return .qFocus
        case .selWash: return .qSelWash
        case .selRule: return .qSelRule
        case .selWashIdle: return .qSelWashIdle
